Object.entries(ENEMY_IMG).forEach(([key, m]) => {
  // Cỡ theo chiều cao; ảnh bề ngang rộng (binh khí, áo choàng xòe) được tràn ngang tới 1,8 lần khung,
  // để người không bị thu nhỏ (người dùng báo 2026-11-10)
  const s = Math.min(230 * 1.8 * m.k / m.w, 300 * m.k / m.h), dw = m.w * s, dh = m.h * s, x = (240 - dw) / 2, y = 304 - dh;
  const f = n => n.toFixed(1);
  ENEMY_ART[key] = {
    label: m.label, img: true,
    crop: `${f(x + m.head[0] * dw)} ${f(y + m.head[1] * dh)} ${f(m.head[2] * dw)} ${f(m.head[2] * dw)}`,
    body: `<ellipse cx="120" cy="301" rx="${f(dw * 0.36)}" ry="9" fill="#2a1a10" opacity="0.16"></ellipse><image href="game/img/quai/${key}.png" x="${f(x)}" y="${f(y)}" width="${f(dw)}" height="${f(dh)}"></image>`,
    hurt: '',
  };
});

// Hình toàn thân của quái trong khung chiến đấu; face 'hurt' = vừa trúng đòn
function enemyArtSvg(key, face) {
  const a = ENEMY_ART[key];
  if (!a) return '';
  // Quái vẽ bằng ảnh có thể to hơn khung (k > 1): không cắt mép
  return `<svg class="avatar body${a.img && face === 'hurt' ? ' en-hurt' : ''}" viewBox="0 0 240 320"${a.img ? ' style="overflow:visible"' : ''} aria-hidden="true">${a.body}${face === 'hurt' ? a.hurt : ''}</svg>`;
}
